mapper.select:
select distinct aa.* from( SELECT I.OURTRADERNAME ourTradeName, case when I.BUSINESSTYPE='T01' then (select TRADE_MARKET from fin_product where FINPROD_market_ID = I.SECURITYID) then I.BUSINESSTYPE='T02' then case when tr.market= 'IB' then '01' when tr.market= 'SH' then '03' when tr.market= 'SZ' then '04' else null end market, if(I.BUSINESSTYPE='T01',ts.SETTLE_SPEED, if (I.BUSINESSTYPE='T02',tr.SETTLE_SPEED, null)) settleSpeed, I.ourdepositaccountname,
I.OURDEPOSITACCOUNTNUMBER ,I.EXECID execid ,I.BUSINESSTYPE businesstype ,if(I.BUSINESSTYPE='T01',I.SECURITYID, if (I.BUSINESSTYPE='T02','',null)) securityid ,if(I.BUSINESSTYPE='T01', I.SYMBOL, if(I.BUSINESSTYPE='T02', '',null)) symbol ,I.SIDE side ,ts.Prinamt prinamt ,tr.Repoamt repoamt ,I.LASTQTY lastqty ,(select sum(MATCH_NUM) from trd_match_info where CSTP_TRADE_ID = I.EXECID) lastqtyready
,if(I.BUSINESSTYPE='T01',I.PRICE,if(I.BUSINESSTYPE='T02',I.PRICE*100,null)) price ,if(I.BUSINESSTYPE= 'T01', I.DIRTYPRICE, if(I.BUSINESSTYPE='T02', '',null)) dirtyprice ,if(I.BUSINESSTYPE= 'T01', I.UNDERLYINGYIELD2*100, if(I.BUSINESSTYPE='T02', '',null)) underlyingyield2 ,I.TRADEDATE tradedate ,if(I.BUSINESSTYPE= 'T01', I.ACCRUEDINTERESTAMT, if(I.BUSINESSTYPE='T02', '',null)) accruedinterestamt ,I.ACCRUEDINTERESTTOTALAMT accruedinteresttotalamt ,I.TRADECASHAMT tradecashamt ,if(I.BUSINESSTYPE= 'T01', '', if(I.BUSINESSTYPE='T02', I.SETTLCURRAMT2,null)) settlcurramt2 ,if(I.BUSINESSTYPE= 'T01', '', if(I.BUSINESSTYPE='T02', I.TRADELIMITDAYS,null)) tradelimitdays ,if(I.BUSINESSTYPE= 'T01', '', if(I.BUSINESSTYPE='T02', I.CASHHOLDINGDAYS,null)) cashholdingdays ,round(if(I.BUSINESSTYPE= 'T01', (IFNULL(I.LASTQTY,0)-IFNULL(ts.Prinamt,0))/IFNULL(I.LASTQTY,0), if(I.BUSINESSTYPE= 'T02',(IFNULL(I.LASTQTY,0)-IFNULL(tr.Repoamt,0))/IFNULL(I.LASTQTY,0),null)),4) percent, if(I.BUSINESSTYPE= 'T01', I.STRIKEYIELD*100, if(I.BUSINESSTYPE='T02', '',null)) strikeyield, CASE WHEN TRD.F_TRADE_ID IS NULL and WFL.F_TRADE_ID is null THEN '02' WHEN ((TRD.F_TRADE_ID IS NOT NULL OR WFL.F_TRADE_ID is NOT null) AND if(I.BUSINESSTYPE='T01',ts.Prinamt, if(I.BUSINESSTYPE='T02',tr.Repoamt,null))=0) then '01' ELSE '03' END matchStatus FROM INTERF_CSTP_TRADE I LEFT JOIN TRD_PRODUCT_DEAL TRD ON TRD.F_TRADE_ID = I.EXECID AND TRD.IS_CANCEL = #{IS_CANCEL} AND TRD.TRADE_STATUS=01 LEFT JOIN TRD_PRODUCT_DEAL_ADD TADD ON TRD.TRADE_ID = TADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO P ON TADD.PORTFOLIO_ID = P.PORTFOLIO_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL WFL ON WFL.F_TRADE_ID = I.EXECID AND WFL.IS_CANCEL = #{IS_CANCEL} AND WFL.TRADE_STATUS=01 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD WADD ON WFL.TRADE_ID = WADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO WP ON WADD.PORTFOLIO_ID = WP.PORTFOLIO_ID left join INTERF_OPICS_TRAD_REPO tr on tr.oritradeid = I.EXECID left join INTERF_TRAD_SECDEAL ts on ts.FEDEALNO = EXECID
AND I.BUSINESSTYPE in ('T01','T02')
AND I.BUSINESSTYPE = #{finprodType}
AND I.SIDE = #{ps}
AND I.SECURITYID = #{finprodId}
AND I.EXECID IN
#{item}
AND (TRADEDATE BETWEEN #{tradeDateBegin} AND #{tradeDateEnd})
AND STR_TO_DATE(TRADEDATE,'%Y-%m-%d') >= STR_TO_DATE(#{entrustStartDate},'%Y-%m-%d') AND STR_TO_DATE(TRADEDATE,'%Y-%m-%d') <= STR_TO_DATE(#{entrustEndDate},'%Y-%m-%d')
and I.OURDEPOSITACCOUNTNUMBER = #{secAcctId}
and I.OURTRADERNAME LIKE concat_ws('','%', #{ourTradeName},'%')
and I.TRADELIMITDAYS >=${repoTerm}
and I.TRADELIMITDAYS <= ${repoTerm2}
and I.TRADECASHAMT >=${priceAmt}
and I.TRADECASHAMT <= ${priceAmt2}
) aa
AND aa.matchStatus IN
#{item}
and aa.market = #{tradeMarket}
and aa.settleSpeed = #{settleSpeed}
and aa.tradelimitdays = #{tradelimitdays}
